import{_ as t,o as d,c as a,a3 as s}from"./chunks/framework.Ch_0qWu9.js";const p=JSON.parse('{"title":"Online Solver backend protocol","description":"","frontmatter":{"sourcePath":"docs/solver-backend.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/29e5ae6c70cf7268cd38de5cf59f4e08507b1ff6/docs/solver-backend.md","alternateUrl":"/TCSExam/docs/zh/solver-backend/","alternateAnchors":{"online-solver-backend-protocol":"online-solver-backend-protocol","deployment-scope":"deployment-scope","credentials-and-attempt-identity":"credentials-and-attempt-identity","session-interface":"session-interface","images-and-deployment":"images-and-deployment"}},"headers":[],"relativePath":"solver-backend/index.md","filePath":"solver-backend/index.md"}'),o={name:"solver-backend/index.md"};function i(n,e,r,c,l,h){return d(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="online-solver-backend-protocol" tabindex="-1">Online Solver backend protocol <a class="header-anchor" href="#online-solver-backend-protocol" aria-label="Permalink to &quot;Online Solver backend protocol&quot;">​</a></h1><p>This reference describes the HTTP interface used by Online Solver clients. It is for service operators and developers implementing a compatible adapter.</p><h2 id="deployment-scope" tabindex="-1">Deployment scope <a class="header-anchor" href="#deployment-scope" aria-label="Permalink to &quot;Deployment scope&quot;">​</a></h2><ol><li><p>Prepare the selected development and judge images with <code>tcsexam build</code>.</p></li><li><p>Configure credentials and start the service using the <a href="/TCSExam/docs/backend/docker/">Docker deployment guide</a> or a <a href="/TCSExam/docs/backend/service/#writing-a-platform-adapter">custom platform adapter</a>.</p></li><li><p>Configure <code>prepare</code>, <code>doctor</code> and <code>run</code> for the chosen deployment:</p><ul><li>Docker deployment: supply the generated <code>--backend-plan PATH</code>, which includes the service address and the worker plan for the selected tasks.</li><li>External service: pass <code>--judge-url URL</code> or set <code>TCSEXAM_BASE_URL</code> to an address reachable from the task containers. A generated Docker plan is optional; without one, the launcher uses each task&#39;s standard worker count, resources and timing recorded under <code>standard_client_timing</code> in the selection record. The service must provide those resources and honor the task budgets.</li></ul></li><li><p>Inspect submission records and final results in the job output.</p></li></ol><p>The clients are <code>tasks/solver/online/&lt;task&gt;/environment/submit.sh</code> and <code>tasks/solver/online/&lt;task&gt;/tests/fetch_final.py</code>. They use the task&#39;s declared instance sets, time budgets and scoring rules.</p><h2 id="credentials-and-attempt-identity" tabindex="-1">Credentials and attempt identity <a class="header-anchor" href="#credentials-and-attempt-identity" aria-label="Permalink to &quot;Credentials and attempt identity&quot;">​</a></h2><p>All requests use authentication. Archive credentials are supplied to the verifier alone. Header names are case insensitive.</p><table tabindex="0"><thead><tr><th>HTTP header</th><th>Value</th></tr></thead><tbody><tr><td><code>X-TCSEXAM-Token-Id</code></td><td><code>TCSEXAM_TOKEN_ID</code></td></tr><tr><td><code>X-TCSEXAM-Token-Secret</code></td><td><code>TCSEXAM_TOKEN_SECRET</code></td></tr><tr><td><code>X-TCSEXAM-Client-Id</code></td><td>Stable identifier for this task attempt</td></tr><tr><td><code>X-TCSEXAM-Run-Id</code></td><td>The same task-attempt identifier</td></tr><tr><td><code>X-TCSEXAM-Agent-Name</code></td><td>Optional <code>TCSEXAM_AGENT_NAME</code></td></tr><tr><td><code>X-TCSEXAM-Archive-Token</code></td><td>Verifier-only credential from <code>/tests/archive_token</code></td></tr></tbody></table><p>Set <code>TCSEXAM_RUN_ID</code> to a unique, stable identifier for each attempt. The clients use the container hostname when it is absent. The backend must isolate different attempts sharing an egress address. Credentials and archive contents must stay scoped to the owning attempt; the model must not receive the archive credential.</p><p>The supplied service checks each session&#39;s declared Run-Id. This separates cooperating callers using shared service credentials. Run-Id is a caller-supplied label; deployments that must prevent deliberate impersonation also need independently authenticated credentials for each attempt. See the service&#39;s <a href="/TCSExam/docs/backend/service/#security-boundaries">security boundaries</a>.</p><p>Use the same header names for foreground requests, background keepalive requests, final judging and audit downloads. The TCSEXAM interface uses this namespace throughout. Hidden-session creation, every creation carrying <code>judge_payload</code>, and every session list/reconciliation query require the archive header in addition to the service token pair. Missing, wrong and unconfigured archive credentials receive 403 on these create/list operations. Public self-test creation without <code>judge_payload</code>, status, submission and result polling use only the service token pair. Send the archive header only to the create/list and archive/payload service endpoints, not through solver submission relays into judge workers.</p><p>Use the TCSExam launcher to pass credentials into the agent and verifier containers. For a custom launcher, populate the task&#39;s <code>${TCSEXAM_*}</code> placeholders and preserve verifier-only credential placement.</p><h2 id="session-interface" tabindex="-1">Session interface <a class="header-anchor" href="#session-interface" aria-label="Permalink to &quot;Session interface&quot;">​</a></h2><p>These paths are relative to <code>TCSEXAM_BASE_URL</code>. The existing clients define exact per-task behavior; the endpoints below show their shared interface.</p><table tabindex="0"><thead><tr><th>Method and path</th><th>Behavior</th></tr></thead><tbody><tr><td><code>POST /v1/judge/sessions</code></td><td>Accept <code>judge_image</code>, <code>ttl</code>, <code>n_shards</code>, <code>resources</code>, and optional <code>instance_set</code> and <code>judge_payload</code>; return <code>session_id</code>. Public self-tests request <code>public</code> and require an exact <code>public_image_map</code> entry. Without a payload they use only service authentication. Omitted instance set defaults to <code>hidden</code>; hidden creation and every creation carrying <code>judge_payload</code> also require the archive header.</td></tr><tr><td><code>GET /v1/judge/sessions</code></td><td>List live and recently destroyed sessions. Requires the archive header; this also applies to the <code>session_ids</code> and <code>client_ip</code> query forms below.</td></tr><tr><td><code>GET /v1/judge/sessions/{id}</code></td><td>Report readiness and failures. Provisioning must finish before judging starts.</td></tr><tr><td><code>POST /v1/judge/sessions/{id}/submit</code></td><td>Accept raw tar.gz with <code>Content-Type: application/gzip</code>; return integer <code>submission</code> after accepting it. Do not send the archive header through this relay.</td></tr><tr><td><code>GET /v1/judge/sessions/{id}/submissions</code></td><td>Return <code>submissions</code>, each with <code>submission</code>, <code>status</code>, and per-instance <code>records</code>. Unfinished submissions use <code>running</code>.</td></tr><tr><td><code>GET /v1/judge/sessions/{id}/archive</code></td><td>Require the archive header and return raw per-shard records, including <code>instance_set</code>, <code>n_shards</code>, <code>shard_payloads</code>, and <code>failed_shards</code>.</td></tr><tr><td><code>GET /v1/judge/sessions?session_ids=a,b</code></td><td>Require the archive header. Return per-session hidden <code>submissions</code>, <code>public_submissions</code> and <code>present</code>; retain counts after resource teardown.</td></tr><tr><td><code>DELETE /v1/judge/sessions/{id}</code></td><td>Release workers while retaining the counts and records needed for verification.</td></tr></tbody></table><p>The optional audit endpoints <code>GET /v1/judge/sessions/{id}/payload/submissions</code> and <code>GET /v1/judge/sessions/{id}/payload/submissions/{seq}</code> list submission numbers and return original uploaded tar bytes. They use the archive header. Unavailable optional payloads are recorded separately from judging failures. The legacy operational query <code>GET /v1/judge/sessions?client_ip=self</code> is optional telemetry and also requires the archive header; it must not decide an attempt&#39;s score or submission allowance.</p><p>A submission is counted once when accepted. HTTP 503 means it has not been accepted and can be retried. An ambiguous upload disconnect must not be retried blindly. The current verifier interprets HTTP 429 on <code>/submit</code> as the submission cap, so the backend must not use that response for ordinary worker congestion. HTTP 410 or <code>error_class=terminal</code> means the session is permanently unavailable.</p><p>Retain every instance&#39;s objective value, validity and status, including instances excluded from a particular score average. Infrastructure failures must remain distinct from valid zero scores. Preserve each task&#39;s time pools, certificate checks, budgets, history-selection rules and public/hidden separation.</p><h2 id="images-and-deployment" tabindex="-1">Images and deployment <a class="header-anchor" href="#images-and-deployment" aria-label="Permalink to &quot;Images and deployment&quot;">​</a></h2><p>Public creation resolves an exact <code>public_image_map</code> key from the requested judge image to a public-only worker image. Missing entries receive HTTP 403 before any worker is created. Hidden creation uses the requested hidden image.</p><p>Prepare images with <code>tcsexam build</code>, or provide an external manifest with immutable backend image assignments. Before registering a public image, follow <a href="/TCSExam/docs/backend/public-images/">public-image preparation</a> to check its inputs and retained layers. Then configure the map and start the service through the <a href="/TCSExam/docs/backend/docker/">Docker guide</a>.</p>',21)])])}const m=t(o,[["render",i]]);export{p as __pageData,m as default};
